public enum RebirthNpcRequirementStatus : byte { IMPLEMENTED=0, PARTIAL=1, NOT_IMPLEMENTED=2 }

public sealed class RebirthNpcRequirementDefinition
{
    public readonly string Id, Domain, Name, PackageId, Documentation, Evidence, PersistenceObligation, NetworkingObligation, UiAdminObligation, CompletionPredicate, Assessment;
    public readonly RebirthNpcRequirementStatus Status;
    public RebirthNpcRequirementDefinition(string id,string domain,string name,string packageId,RebirthNpcRequirementStatus status,string documentation,string evidence,string persistence,string networking,string uiAdmin,string predicate,string assessment)
    { Id=id; Domain=domain; Name=name; PackageId=packageId; Status=status; Documentation=documentation; Evidence=evidence; PersistenceObligation=persistence; NetworkingObligation=networking; UiAdminObligation=uiAdmin; CompletionPredicate=predicate; Assessment=assessment; }
}

public sealed class RebirthNpcConformanceGateResult
{
    public string Gate; public bool Passed; public string Detail;
}

public sealed class RebirthNpcConformanceReport
{
    public string PackageId; public bool Passed; public int RequirementCount; public RebirthNpcConformanceGateResult[] Gates;
    public string ToReport() { StringBuilder b=new StringBuilder("[REBIRTH NPC Conformance] package=").Append(PackageId).Append(" result=").Append(Passed?"PASS":"FAIL").Append(" requirements=").Append(RequirementCount); for(int i=0;i<Gates.Length;i++) b.Append('\n').Append(Gates[i].Gate).Append('=').Append(Gates[i].Passed?"PASS":"FAIL").Append(" (").Append(Gates[i].Detail).Append(')'); return b.ToString(); }
}

