    public static RebirthNpcRequirementDefinition[] GetAll() { return (RebirthNpcRequirementDefinition[])Definitions.Clone(); }
    public static RebirthNpcRequirementDefinition[] GetByPackage(string packageId) { List<RebirthNpcRequirementDefinition> result=new List<RebirthNpcRequirementDefinition>(); for(int i=0;i<Definitions.Length;i++) if(string.Equals(Definitions[i].PackageId,packageId,StringComparison.OrdinalIgnoreCase)) result.Add(Definitions[i]); return result.ToArray(); }
    public static RebirthNpcRequirementDefinition Find(string id) { for(int i=0;i<Definitions.Length;i++) if(string.Equals(Definitions[i].Id,id,StringComparison.OrdinalIgnoreCase)) return Definitions[i]; return null; }
    public static int Count { get { return Definitions.Length; } }
}

public static class RebirthNpcConformanceControlPlane
{
    private static long runs,passes,failures;
    public static RebirthNpcConformanceReport Run(string packageId)
    {
        Interlocked.Increment(ref runs);
        string id=string.IsNullOrEmpty(packageId)?"ACIP-00":packageId.Trim().ToUpperInvariant();
        RebirthNpcRequirementDefinition[] assigned=RebirthNpcRequirementCatalogue.GetByPackage(id);
        List<RebirthNpcConformanceGateResult> gates=new List<RebirthNpcConformanceGateResult>();
        Add(gates,"catalogueCount",RebirthNpcRequirementCatalogue.Count==127,"count="+RebirthNpcRequirementCatalogue.Count+" expected=127");
        Add(gates,"stableIds",ValidateStableIds(),"unique immutable NPC-REQ-### IDs");
        Add(gates,"packageAssignment",assigned.Length>0,"assigned="+assigned.Length);
        Add(gates,"completionPredicates",AllPredicatesPresent(assigned),"all assigned rows have explicit predicates");
        Add(gates,"traceabilityEvidence",AllEvidencePresent(assigned),"all assigned rows have source/caller evidence");
        RebirthNpcLifecycleSnapshot life=RebirthNpcLifecycle.GetSnapshot();
        Add(gates,"runtimeRegistration",Contains(life.RegisteredServices,typeof(RebirthNpcConformanceControlPlane).FullName),"lifecycle service registration");
        Add(gates,"callerRegistration",Contains(life.RegisteredServices,typeof(RebirthNpcRequirementCatalogue).FullName),"catalogue registered and callable through rbnpc conformance");
        Add(gates,"placeholderRejection",NoPlaceholderOnlyPass(assigned),"partial/missing rows cannot pass");
        bool pass=true; for(int i=0;i<gates.Count;i++) if(!gates[i].Passed){pass=false;break;}
        if(pass) Interlocked.Increment(ref passes); else Interlocked.Increment(ref failures);
        return new RebirthNpcConformanceReport { PackageId=id, Passed=pass, RequirementCount=assigned.Length, Gates=gates.ToArray() };
    }
    public static string GetReport(string packageId) { return Run(packageId).ToReport()+"\n"+GetCounters(); }
    public static string GetCounters() { return "runs="+Interlocked.Read(ref runs)+" passes="+Interlocked.Read(ref passes)+" failures="+Interlocked.Read(ref failures); }
    private static void Add(List<RebirthNpcConformanceGateResult> list,string gate,bool pass,string detail){list.Add(new RebirthNpcConformanceGateResult{Gate=gate,Passed=pass,Detail=detail});}
    private static bool ValidateStableIds(){HashSet<string> ids=new HashSet<string>(StringComparer.Ordinal);RebirthNpcRequirementDefinition[] all=RebirthNpcRequirementCatalogue.GetAll();for(int i=0;i<all.Length;i++){if(!ids.Add(all[i].Id)||all[i].Id!="NPC-REQ-"+(i+1).ToString("000"))return false;}return true;}
    private static bool AllPredicatesPresent(RebirthNpcRequirementDefinition[] values){for(int i=0;i<values.Length;i++)if(string.IsNullOrWhiteSpace(values[i].CompletionPredicate))return false;return true;}
    private static bool AllEvidencePresent(RebirthNpcRequirementDefinition[] values){for(int i=0;i<values.Length;i++)if(string.IsNullOrWhiteSpace(values[i].Evidence))return false;return true;}
    private static bool NoPlaceholderOnlyPass(RebirthNpcRequirementDefinition[] values){for(int i=0;i<values.Length;i++)if(values[i].Status!=RebirthNpcRequirementStatus.IMPLEMENTED)return false;return true;}
    private static bool Contains(string[] values,string expected){if(values==null)return false;for(int i=0;i<values.Length;i++)if(string.Equals(values[i],expected,StringComparison.Ordinal))return true;return false;}
}
